const s=JSON.parse(document.querySelector('#simulator-data').textContent),exposure=document.querySelector('#exposure'),status=document.querySelector('#status');function run(){let total=0;for(const r of s.risks){const p=Number(document.querySelector('[data-risk="'+r.id+'"][data-field="probability"]').value),i=Number(document.querySelector('[data-risk="'+r.id+'"][data-field="impact"]').value);total+=p*i}const score=Math.round(total/(s.risks.length*25)*1000)/10;exposure.textContent=score.toFixed(1);status.textContent=score<30?'LOW':score<60?'MEDIUM':'HIGH'}for(const input of document.querySelectorAll('input'))input.addEventListener('input',()=>{input.nextElementSibling.value=input.value});document.querySelector('#calculate-risk').addEventListener('click',run);run();
